def average(*args) -> float:
    """ The average function receives zero or more arguments, and return its average value.
    >>> average(1,3,4,5)
    3.0
    """
    sum = 0
    if len(args) == 0:
        return sum
    else:
        for i in args:
            sum += i
    return sum / len(args)

def gcd(x: int, y: int) -> int:
    """ The gcd function return the gcd of two positive integers.
    >>> gcd(12, 4)
    4
    """
    if x == 0:
        return y
    elif y == 0:
        return x
    else:
        if x > y:
            return gcd(x-y, y)
        else:
            return gcd(x, y-x)

