def max_level_nesting(paren_string: str) -> int:
    """ Input to this function is a string represented multiple groups of parentheses separated by spaces.
    For each of the group, output the maximum level of nesting.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> max_level_nesting('(()()) ((())) () ((())()())')
    3
    """
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(1)
        elif char == ')':
            if stack:
                stack.pop()
                len_parens = len(stack)
                stack[-1] += 1
                return len_parens
    return len(stack)


