def filter_litter(litter: List[str], *keywords) -> List[str]:
    """ Return list of elements from the given litter which not
    contained in the list of keywords.
    >>> filter_litter(['apples', 'bananas', 'pears'], 'pears', 'grapes')
    ['apples', 'bananas']
