def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Median.
    Median is the center value for a given dataset:
    >>> median([1, 2, 3, 4, 5])
    3.0
    >>> median([3, 1, 2, 5, 4])
    3.0
    """
    n = len(numbers)
    if n == 0:
        return 0
    elif n == 1:
        return numbers[0]
    else:
        n = n // 2
        if n % 2 == 0:
            left = numbers[:n]
            right = numbers[n:]
            mid = (left[-1] + right[0]) / 2
            return (mid + left[-1]) / 2
        else:
            return numbers

    mean = sum(numbers) / len(numbers)
    return sum(abs(num - mean) for num in numbers) / len(numbers)


